from django.core.exceptions import ValidationError
from django.db import models

# Test 1: Default behavior - ValidationError should have default code (None)
class Product1(models.Model):
    price = models.IntegerField()
    class Meta:
        app_label = 'test'
        constraints = [
            models.CheckConstraint(check=models.Q(price__gt=0), name='price_positive')
        ]

constraint1 = models.CheckConstraint(check=models.Q(price__gt=0), name='price_positive')
product = Product1(price=-1)
try:
    constraint1.validate(Product1, product)
except ValidationError as e:
    print(f"Test 1 - Default code: {e.code}")  # Should be None

# Test 2: Custom violation_error_code (what we want to add)
# Currently this parameter doesn't exist
try:
    constraint2 = models.CheckConstraint(
        check=models.Q(price__gt=0),
        name='price_positive2',
        violation_error_code='custom_code'
    )
    print("Test 2 - Custom violation_error_code parameter accepted: PASS")
except TypeError as e:
    print(f"Test 2 - Custom violation_error_code parameter accepted: FAIL - {e}")

# Test 3: After fix, ValidationError should have custom code
try:
    constraint3 = models.CheckConstraint(
        check=models.Q(price__gt=0),
        name='price_positive3',
        violation_error_code='price_must_be_positive'
    )
    product3 = Product1(price=-1)
    constraint3.validate(Product1, product3)
except ValidationError as e:
    print(f"Test 3 - Custom code: {e.code}")  # Should be 'price_must_be_positive'

print("\nAll tests completed!")
EOF
